//! Structured Execution Plan data model (Phase 1.2).
//!
//! Represents an auditable, multi-step engineering plan generated by the
//! Planner Agent. Each step is a typed capability with explicit blast-radius
//! scoring, preconditions, and paired compensating rollback steps.

use capability_layer::CapabilityKind;
use serde::{Deserialize, Serialize};

use crate::policy::BlastRadiusReport;

/// Status of an execution plan.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PlanStatus {
    /// Plan drafted by the Planner, pending user review or approval.
    Draft,
    /// Approved by the user or cleared by policy gate; ready for execution.
    Approved,
    /// Currently being executed step-by-step by the Implementer.
    Executing,
    /// All steps succeeded and verified by the Test/Verification Agent.
    Completed,
    /// A step failed or was denied; forward execution halted.
    Failed,
    /// Compensating rollback actions were executed following a failure.
    RolledBack,
}

/// An atomic step within an execution plan.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct PlanStep {
    /// Step identifier, e.g. "step-1".
    pub step_id: String,
    /// Human-readable description of this step's purpose.
    pub description: String,
    /// The typed capability to execute.
    pub capability: CapabilityKind,
    /// Blast-radius report for this specific step.
    pub blast_radius: BlastRadiusReport,
    /// Timeout in seconds before treating step as hung (default 30s).
    pub timeout_secs: u64,
}

/// A compensating rollback action to execute if a plan fails mid-flight.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct RollbackStep {
    /// Rollback step identifier, e.g. "rollback-step-1".
    pub step_id: String,
    /// Human-readable explanation of how this step restores state.
    pub description: String,
    /// Capability action to undo changes (e.g. restoring previous file content).
    pub capability: CapabilityKind,
    /// List of forward step IDs whose failure triggers this rollback step.
    pub triggers: Vec<String>,
}

/// Complete multi-step plan produced by the Planner Agent.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Plan {
    /// Unique correlation identifier for this plan (e.g. UUID).
    pub id: String,
    /// High-level user intent that initiated this plan.
    pub intent: String,
    /// Detailed engineering summary of the planned actions.
    pub summary: String,
    /// Ordered sequence of forward capability steps to execute.
    pub steps: Vec<PlanStep>,
    /// Compensating rollback steps to execute in reverse if any forward step fails.
    pub rollback_steps: Vec<RollbackStep>,
    /// Aggregate blast radius and approval tier across the entire plan.
    pub aggregate_blast_radius: BlastRadiusReport,
    /// ISO-8601 creation timestamp.
    pub created_at: String,
    /// Current lifecycle status of the plan.
    pub status: PlanStatus,
}

impl Plan {
    /// Returns all forward capabilities in this plan.
    pub fn capabilities(&self) -> Vec<CapabilityKind> {
        self.steps.iter().map(|s| s.capability.clone()).collect()
    }

    /// Finds a step by its ID.
    pub fn find_step(&self, step_id: &str) -> Option<&PlanStep> {
        self.steps.iter().find(|s| s.step_id == step_id)
    }
}

/// Detailed outcome of executing an individual step.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct StepExecutionResult {
    /// Step identifier.
    pub step_id: String,
    /// Whether the capability call succeeded.
    pub success: bool,
    /// Machine-readable result payload or error description.
    pub details: serde_json::Value,
    /// Sequence number of the audit log entry recorded for this call.
    pub audit_seq: u64,
    /// Execution duration in milliseconds.
    pub duration_ms: u64,
}

/// Final summary report after executing an entire plan.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct PlanExecutionReport {
    /// Plan identifier.
    pub plan_id: String,
    /// Final status (`Completed`, `Failed`, or `RolledBack`).
    pub final_status: PlanStatus,
    /// Results for each attempted forward step.
    pub step_results: Vec<StepExecutionResult>,
    /// Results for any executed rollback steps.
    pub rollback_results: Vec<StepExecutionResult>,
    /// Total execution time in milliseconds.
    pub total_duration_ms: u64,
    /// Human-readable explanation of the final outcome.
    pub message: String,
}
